  if(path.startsWith("/api/diagnosis/"))return{module:"Repairs",action:payload.diagnosisCompleted?"Complete Diagnosis":"Save Diagnosis Draft",reference:id};
  if(path.startsWith("/api/collections"))return{module:"Ready for Collection",action:path.endsWith("/notify")?"Notify Customer":payload.markCollected?"Record Collection":"Update Collection",reference:created||payload.repairNo||id};
  if(path.startsWith("/api/repairs"))return{module:"Repairs",action:method==="POST"?"Create Repair":"Update Repair",reference:created||payload.no||id};
  if(path.startsWith("/api/onsite-service"))return{module:"Onsite Service",action:path.endsWith("/create-repair")?"Create Linked Repair":method==="POST"?"Create Service Request":"Update Service Request",reference:created||payload.no||id};
