  if(path.includes("/undo-send"))return{module:"Warranty",action:"Return Send to Preparation",reference:id,severity:"High"};
  if(path.includes("/supplier-reminder"))return{module:"Warranty",action:"Email Supplier Reminder",reference:id};
  if(path.includes("/sent-confirmation"))return{module:"Warranty",action:`${payload.type||"Record"} Sent Confirmation`,reference:id};
  if(path.endsWith("/return")&&path.startsWith("/api/warranty/"))return{module:"Warranty",action:"Record Supplier Return",reference:id,severity:"High"};
  if(path.startsWith("/api/warranty/direct"))return{module:"Warranty",action:"Create Direct Warranty Claim",reference:responseData?.warranty?.id||created};
  if(path.startsWith("/api/warranty"))return{module:"Warranty",action:method==="POST"?"Create Warranty Claim":"Update Warranty Claim",reference:created||payload.id||id};
  if(path.includes("/sign")&&path.startsWith("/api/service-contracts"))return{module:"Service Contracts",action:"Sign Contract",reference:id,severity:"High"};
  if(path.includes("/renew")&&path.startsWith("/api/service-contracts"))return{module:"Service Contracts",action:"Renew Contract",reference:created||id,severity:"High"};
